import { test, expect } from '@playwright/test';

test.describe('Modal Content Independent Scrolling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-page');
  });

  test('should scroll modal content independently when it overflows', async ({ page }) => {
    // Open modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Verify modal content is scrollable
    const modalContent = page.locator('[data-testid="modal-content"]');
    const scrollbar = page.locator('[data-testid="modal-scrollbar"]');
    await expect(scrollbar).toBeVisible();

    // Scroll modal content to the bottom
    await modalContent.evaluate((el) => {
      el.scrollTop = el.scrollHeight;
    });

    // Verify scrollbar is at the bottom
    await expect(scrollbar).toHaveAttribute('style', /bottom: 0px/);

    // Verify modal container is not scrolled
    const modalContainer = page.locator('[data-testid="modal-container"]');
    const containerScrollTop = await modalContainer.evaluate((el) => el.scrollTop);
    expect(containerScrollTop).toBe(0);

    // Verify modal content is visible
    const contentText = page.locator('[data-testid="modal-content"]').textContent();
    expect(contentText).toContain('End of content');
  });

  test('should not scroll modal content when it does not overflow', async ({ page }) => {
    // Open modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Verify modal content is not scrollable
    const modalContent = page.locator('[data-testid="modal-content"]');
    const scrollbar = page.locator('[data-testid="modal-scrollbar"]');
    await expect(scrollbar).not.toBeVisible();

    // Verify modal container is not scrolled
    const modalContainer = page.locator('[data-testid="modal-container"]');
    const containerScrollTop = await modalContainer.evaluate((el) => el.scrollTop);
    expect(containerScrollTop).toBe(0);

    // Verify modal content is fully visible
    const contentText = page.locator('[data-testid="modal-content"]').textContent();
    expect(contentText).toContain('Start of content');
    expect(contentText).toContain('End of content');
  });
});
